#!/usr/bin/env python3
"""Compute ground truth for CSX-317_Q1 from the local CSX-317 package."""

from __future__ import annotations

import csv
import html
import json
import math
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-317_Q1"
PACKAGE_ID = "CSX-317"
DIFFICULTY_LEVEL = "L2"

RUBRIC = [
    {
        "name": "exact structured core",
        "points": 4,
        "description": (
            "Gives the exact mechanism label glacier_collapse_lake_outburst_downvalley_flood, "
