            "Connects the 15-minute travel time and large threatened population to critical "
            "rapid-impact emergency planning."
        ),
        "partial_credit": "Award partial credit for generic emergency concern without tying it to travel time and population.",
    },
    {
        "name": "rejection of alternatives and overclaims",
        "points": 2,
        "description": (
            "Rejects rainfall-only flooding, coastal surge, slow seasonal snowmelt, precise modern "
            "casualty estimates, and unprovided depth/discharge claims."
        ),
        "partial_credit": "Award partial credit for avoiding overclaims without explicitly explaining why distractors fail.",
    },
]


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def read_json(root: Path, relative_path: str) -> Any:
    return json.loads((root / relative_path).read_text(encoding="utf-8", errors="replace"))


def read_text(root: Path, relative_path: str) -> str:
    return (root / relative_path).read_text(encoding="utf-8", errors="replace")


def strip_html(raw_html: str) -> str:
    text = re.sub(r"<script\b.*?</script>", " ", raw_html, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<style\b.*?</style>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    text = text.replace("\u2019", "'").replace("\u201c", '"').replace("\u201d", '"')
    text = re.sub(r"(?<=[a-z])(?=[A-Z])", " ", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def first_int(pattern: str, text: str) -> int:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return int(match.group(1).replace(",", ""))


def snippet(text: str, pattern: str, radius: int = 180) -> str:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        return ""
    start = max(0, match.start() - radius)
    end = min(len(text), match.end() + radius)
    return text[start:end].strip()


def count_manifest_categories(package_dir: Path) -> dict[str, int]:
    with (package_dir / "metadata/files.csv").open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    counts: dict[str, int] = {}
    for row in rows:
        category = row["data_category"]
        counts[category] = counts.get(category, 0) + 1
    return dict(sorted(counts.items()))


def priority_class(index: float) -> str:
    if index >= 15:
        return "critical"
    if index >= 10:
        return "high"
    if index >= 5:
        return "moderate"
    return "low"


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    root = package_root()

    event = read_json(root, "metadata/event.json")
    anchor = read_json(root, "data/event_reports/event_reports_004_Locked_event_anchor_Lake_Palcacocha_GLOF_Huaraz_flood.json")
    open_meteo = read_json(root, "data/physical_hazard/physical_hazard_001_Open-Meteo_archive_point_sample.json")
    exposure = read_json(root, "data/exposure_impact/exposure_impact_001_Overpass_small_critical-amenity_sample.json")
    aoi = read_json(root, "data/geospatial_context/geospatial_context_002_compact_per-event_AOI_derived_from_event_bbox.json")
    eonet = read_json(root, "data/event_catalogs/event_catalogs_003_NASA_EONET_events_API.xml")
    wiki_search = read_json(root, "data/other/other_003_01_event_specific_wikipedia_search_Wikipedia_search_for_exact_event_name.json.json")

    nasa_path = "data/event_reports/event_reports_001_Locked_package_evidence_report.html"
    nasa_text = strip_html(read_text(root, nasa_path))

    threatened_city_population = first_int(r"city of ([\d,]+)", nasa_text)
    flood_arrival_minutes = first_int(r"take ([\d,]+) minutes to reach the city", nasa_text)
    historical_fatalities = first_int(r"killing ([\d,]+) people", nasa_text)
    event_precipitation_mm = float(open_meteo["daily"]["precipitation_sum"][0])
    wind_speed_kmh = float(open_meteo["daily"]["wind_speed_10m_max"][0])
    temperature_max_c = float(open_meteo["daily"]["temperature_2m_max"][0])

    mechanism_flags = {
        "glacier_chunk_threatens_lake": bool(re.search(r"chunk of glacier.*fall into an Andean lake", nasa_text, re.IGNORECASE)),
        "fissure_in_glacier": bool(re.search(r"fissure.*glacier.*Lake Palcacocha", nasa_text, re.IGNORECASE)),
        "rapid_downvalley_arrival": flood_arrival_minutes <= 30,
        "historical_overflow_fatalities": historical_fatalities >= 1000,
        "rainfall_present_but_not_primary": event_precipitation_mm > 0,
    }

    index = (
        math.log10(threatened_city_population)
        + historical_fatalities / 1000.0
        + max(0.0, 60.0 - flood_arrival_minutes) / 10.0
    )

    if (
        event["hazard_family"] == "cryosphere_avalanche_glof_snowmelt"
        and mechanism_flags["glacier_chunk_threatens_lake"]
        and mechanism_flags["fissure_in_glacier"]
        and mechanism_flags["rapid_downvalley_arrival"]
    ):
        answer = "glacier_collapse_lake_outburst_downvalley_flood"
    else:
        answer = "mixed_or_uncertain_flood_mechanism"

    elements = exposure.get("elements", [])
    amenity_counts: dict[str, int] = {}
    for item in elements:
        amenity = (item.get("tags") or {}).get("amenity")
        if amenity:
            amenity_counts[amenity] = amenity_counts.get(amenity, 0) + 1

    coords = aoi["geometry"]["coordinates"][0]
    lons = [point[0] for point in coords]
    lats = [point[1] for point in coords]

    result = {
        "schema_version": "crossscale_extreme_event_bench_v1",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": DIFFICULTY_LEVEL,
        "primary_gt": {
            "answer_type": "exact_structured_core_with_judged_explanation",
            "answer": answer,
            "priority_class": priority_class(index),
            "priority_index": round(index, 2),
            "priority_index_tolerance": 0.01,
            "key_metrics": {
                "threatened_city_population": threatened_city_population,
                "flood_arrival_minutes": flood_arrival_minutes,
                "historical_fatalities": historical_fatalities,
                "event_precipitation_mm": round(event_precipitation_mm, 1),
            },
            "impact_chain": ["glacier_collapse_or_icefall", "lake_outburst_flood", "rapid_downvalley_city_impact"],
            "canonical_stance": (
                "Lake Palcacocha poses a glacier-collapse or icefall-driven glacial-lake outburst flood "
                "threat to Huaraz, giving a critical rapid-impact priority."
            ),
        },
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date": anchor["temporal_window"]["start_date"],
            "region": event["region"],
            "scale": event["scale"],
            "priority_formula": "log10(population) + fatalities/1000 + max(0, 60 - arrival_minutes)/10",
            "priority_components": {
                "log10_population": round(math.log10(threatened_city_population), 4),
                "fatality_component": round(historical_fatalities / 1000.0, 4),
                "rapid_arrival_component": round(max(0.0, 60.0 - flood_arrival_minutes) / 10.0, 4),
            },
            "weather_context": {
                "temperature_max_c": round(temperature_max_c, 1),
                "precipitation_sum_mm": round(event_precipitation_mm, 1),
                "wind_speed_max_kmh": round(wind_speed_kmh, 1),
            },
            "amenity_counts_from_local_overpass_sample": dict(sorted(amenity_counts.items())),
            "eonet_event_count": len(eonet.get("events", [])),
            "wikipedia_search_hits": wiki_search.get("query", {}).get("searchinfo", {}).get("totalhits"),
            "aoi_bbox": {
                "min_lon": min(lons),
                "min_lat": min(lats),
                "max_lon": max(lons),
                "max_lat": max(lats),
            },
            "file_category_counts": count_manifest_categories(root),
            "mechanism_flags": mechanism_flags,
            "judge_anchors": {
                "required_claims": [
                    "Identifies glacier collapse, icefall, or a glacier chunk entering Lake Palcacocha as the trigger.",
                    "Describes the resulting lake outburst or overflow flood moving rapidly down-valley toward Huaraz.",
                    "Uses the 15-minute travel time as a low-warning-time emergency-planning anchor.",
                    "Treats precipitation as contextual rather than the dominant flood mechanism.",
                ],
                "required_metrics": [
                    {"name": "threatened_city_population", "value": threatened_city_population, "unit": "people"},
                    {"name": "flood_arrival_minutes", "value": flood_arrival_minutes, "unit": "minutes"},
                    {"name": "historical_fatalities", "value": historical_fatalities, "unit": "people"},
                    {"name": "event_precipitation_mm", "value": round(event_precipitation_mm, 1), "unit": "mm"},
                    {"name": "priority_index", "value": round(index, 2), "tolerance": 0.01},
                ],
                "forbidden_claims": [
                    "Treats the event as primarily a rainfall-only river flood.",
                    "Attributes the impact mechanism to coastal surge or slow seasonal snowmelt.",
                    "Uses the historical fatality count as a precise modern casualty forecast.",
                    "Claims specific inundation depth, discharge, or modeled flood extent not established by the record.",
                    "Uses outside-source values to replace the supported population, travel-time, fatality, or precipitation values.",
                ],
                "acceptable_variants": [
                    "The trigger may be phrased as glacier collapse, icefall, glacier chunk failure, or ice entering the lake.",
                    "The flood process may be phrased as GLOF, lake outburst, lake overflow, or displacement wave leading to down-valley flooding.",
                    "Priority index values from 16.27 to 16.29 are acceptable if the class remains critical.",
                ],
            },
        },
        "text_claims": {
            "mechanism_claim": snippet(nasa_text, r"chunk of glacier"),
            "arrival_claim": snippet(nasa_text, r"15 minutes"),
            "historical_impact_claim": snippet(nasa_text, r"killing 7,000 people"),
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "metadata/files.csv",
                nasa_path,
                "data/event_reports/event_reports_004_Locked_event_anchor_Lake_Palcacocha_GLOF_Huaraz_flood.json",
                "data/physical_hazard/physical_hazard_001_Open-Meteo_archive_point_sample.json",
                "data/exposure_impact/exposure_impact_001_Overpass_small_critical-amenity_sample.json",
                "data/geospatial_context/geospatial_context_002_compact_per-event_AOI_derived_from_event_bbox.json",
                "data/event_catalogs/event_catalogs_003_NASA_EONET_events_API.xml",
                "data/other/other_003_01_event_specific_wikipedia_search_Wikipedia_search_for_exact_event_name.json.json",
            ],
        },
        "rubric": {
            "total_points": 20,
            "criteria": RUBRIC,
        },
    }

    (task_dir / "computed_gt.json").write_text(json.dumps(result, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
